function Get-SectionObjective {
  param(
    [string]"'$SectionId,
    [string[]]$Lines,
    [int]$Index
  )

  $comment = $null
  for ($j = $Index + 1; $j -lt [Math]::Min($Index + 5, $Lines.Count); $j++) {
    if ($Lines[$j] -match '"'<"'!--'"\\s*(?<comment>.*?)\\s*-->') {
      "'$comment = $Matches.comment.Trim()
      break
    }
    if ($Lines[$j].Trim() -ne '"'') {
      break
    }
  }

  if ([string]::IsNullOrWhiteSpace("'$comment)) {
    $comment = ($SectionId -replace '"'-', ' ')
  }

  "'$comment = $comment -replace '"'\\s+', ' '
  return \"Detalhar "'$comment para consolidar as informações necessárias desta seção, apoiar decisões da etapa e manter o artefato final coerente, acionável e fácil de validar."
}

function Get-MainObjective {
  param([string]$FileName)

  $stage = [regex]::Match($FileName, '"'"'^(?<stage>'"\\d+(?:\\.\\d+)?)').Groups['stage'].Value
  if ([string]::IsNullOrWhiteSpace("'$stage)) {
    $stage = '"'documento'
    return 'Centralizar o conteúdo do documento, reunindo contexto, decisões, regras e entregas esperadas em um único ponto de referência para orientar a produção do artefato final e a continuidade do fluxo de trabalho.'
  }

  return \"Centralizar o conteúdo da Etapa "'$stage, reunindo contexto, decisões, regras e entregas esperadas em um único ponto de referência para orientar a produção do artefato final e a continuidade do fluxo de trabalho."
}

foreach ($file in $files) {
  $path = Join-Path $PWD $file
  $content = [System.IO.File]::ReadAllText($path)
  $lines = $content -split "`r?`n", 0, '"'RegexMatch'
  "'$newLines = New-Object '"'System.Collections.Generic.List[string]'
  "'$mainObjective = Get-MainObjective -FileName $file
  $isTextPrompt = $file -in @('"'0-prompt.md', '0.1-prompt.md')

  for ("'$i = 0; $i -lt $lines.Count; $i++) {
    $line = $lines[$i]

    if ($file -eq '"'13.1-prompt.md' -and "'$line -match '"'"'^(?<indent>'"\\s*)<section>"'$'"') {
      "'$objective = '"'Renderizar o bloco de conteúdo com semântica clara, preservando a relação entre título, objetivo e conteúdo para facilitar leitura, validação e implementação da saída final.'
      "'$newLines.Add("$($Matches.indent)<section data-objetivo='"\\\""'$objective'"\\\">\")
      continue
    }

    if (-not "'$isTextPrompt -and $line -match '"'"'^(?<indent>'"\\s*)<main class=\"content\">') {
      "'$newLines.Add("$($Matches.indent)<main class='"\\\"content\\\" data-objetivo=\\\""'$mainObjective'"\\\">\")
      continue
    }

    if (-not "'$isTextPrompt -and $line -match '"'"'^(?<indent>'"\\s*)<section id=\"(?<id>["'^"]+)">'"') {
      "'$objective = Get-SectionObjective -SectionId $Matches.id -Lines $lines -Index $i
      $newLines.Add("$($Matches.indent)<section id='"\\\""'$($Matches.id)'"\\\" data-objetivo=\\\""'$objective'"\\\">\")
      continue
    }

    if ("'$isTextPrompt -and $file -eq '"'0-prompt.md' -and "'$line -match '"'"'^'"\\* Considerar dark mode e light mode quando aplicável\\.') {
      "'$newLines.Add($line)
      $newLines.Add('"'* Sempre que a saída gerar HTML, aplicar "'`data-objetivo` em `main.content` e em cada `section`, com textos descritivos e específicos para a etapa e para a função de cada bloco.'"')
      continue
    }

    if ("'$isTextPrompt -and $file -eq '"'0.1-prompt.md' -and "'$line -match '"'"'^# Regra Fundamental$'"') {
      "'$newLines.Add($line)
      $newLines.Add('"'')
      "'$newLines.Add('"'* Quando o resultado final incluir HTML, cada "'`main.content` deve ter `data-objetivo` e cada `section` também, com texto objetivo e detalhado sobre sua função.'"')
      continue
    }

    "'$newLines.Add($line)
  }

  $updated = ($newLines -join "`r`n")
  [System.IO.File]::WriteAllText($path, $updated, (New-Object System.Text.UTF8Encoding($false)))
}
'

